# 08_generate_main_figures.R
# Ribeiro Classification Score (RCS)
#
# Main figures:
#   Figure 2 — Synthetic validation heatmap
#   Figure 3 — Combinatorial distribution of admissible grades
#   Figure 4 — Threshold stability and grade-transition matrix
#   Figure 5 — Runtime scalability
#
# Supplementary figures:
#   None generated by design.
#
# Supplementary audit tables:
#   Additional_File_S4 onward, when source tables are available.
#
# Editorial rule:
#   Long captions/titles belong in the manuscript, not inside figures.
# ==========================================================

options(warn = 1, scipen = 999)

