theme_rcs <- function(base_size = 13) {
  ggplot2::theme_minimal(base_size = base_size, base_family = "sans") +
    ggplot2::theme(
      plot.background = ggplot2::element_rect(fill = "white", colour = NA),
      panel.background = ggplot2::element_rect(fill = "white", colour = NA),
      panel.grid.major = ggplot2::element_line(colour = "#E0E0E0", linewidth = 0.35),
      panel.grid.minor = ggplot2::element_blank(),
      axis.title = ggplot2::element_text(colour = "#222222", size = base_size + 1),
      axis.text = ggplot2::element_text(colour = "#4A4A4A", size = base_size),
      strip.text = ggplot2::element_text(
        colour = "#222222",
        face = "bold",
        size = base_size + 2,
        margin = ggplot2::margin(b = 6)
      ),
      legend.position = "bottom",
      legend.title = ggplot2::element_text(size = base_size),
      legend.text = ggplot2::element_text(size = base_size - 1),
      legend.box = "vertical",
      legend.margin = ggplot2::margin(t = 6, r = 8, b = 8, l = 8),
      legend.box.margin = ggplot2::margin(t = 6, r = 8, b = 8, l = 8),
      plot.margin = ggplot2::margin(t = 12, r = 18, b = 18, l = 18)
    )
}

theme_rcs_compact <- function(base_size = 11) {
  theme_rcs(base_size = base_size) +
    ggplot2::theme(
      axis.title = ggplot2::element_text(size = base_size + 1),
      axis.text = ggplot2::element_text(size = base_size),
      strip.text = ggplot2::element_text(size = base_size + 1),
      plot.margin = ggplot2::margin(t = 8, r = 8, b = 8, l = 8)
    )
}

# ==========================================================
# 3. Utility functions
# ==========================================================

clean_names <- function(df) {
  names(df) <- names(df) |>
    stringr::str_replace_all("[^A-Za-z0-9]+", "_") |>
    stringr::str_replace_all("_+", "_") |>
    stringr::str_replace_all("^_|_$", "") |>
    tolower()
  df
}

find_col <- function(df, candidates, required = TRUE, label = "column") {
  candidates <- tolower(candidates)
  hit <- intersect(candidates, names(df))

  if (length(hit) == 0) {
    if (required) {
      stop(
        "Could not find required ", label, ". Tried: ",
        paste(candidates, collapse = ", "),
        "\nAvailable columns: ",
        paste(names(df), collapse = ", ")
      )
    }
    return(NA_character_)
  }

  hit[[1]]
}

parse_num <- function(x) {
  if (is.numeric(x)) return(x)

  x_chr <- as.character(x)
  x_chr <- stringr::str_trim(x_chr)

  x_chr <- ifelse(
    stringr::str_detect(x_chr, ",") & !stringr::str_detect(x_chr, "\\."),
    stringr::str_replace_all(x_chr, ",", "."),
    x_chr
  )

  readr::parse_number(x_chr)
}

normalize_matrix <- function(x) {
  x <- tolower(as.character(x))

  dplyr::case_when(
    stringr::str_detect(x, "fluid|fluido") ~ "fluid",
    stringr::str_detect(x, "solid|sólido|solido") ~ "solid",
    TRUE ~ x
  )
}

normalize_grade <- function(x) {
  x <- stringr::str_trim(as.character(x))
  x <- stringr::str_replace_all(x, "Category", "Grade")
  x <- stringr::str_replace_all(x, "grade", "Grade")
  x <- stringr::str_replace_all(x, "^([A-E])$", "Grade \\1")
  x <- stringr::str_replace_all(x, "^Grade\\s*([A-E]).*$", "Grade \\1")
  x
}

normalize_scenario <- function(x) {
  x0 <- tolower(as.character(x))
  x0 <- stringr::str_replace_all(x0, "_", " ")
  x0 <- stringr::str_squish(x0)

  dplyr::case_when(
    stringr::str_detect(x0, "optimal") &
      !stringr::str_detect(x0, "mild|moderate|severe") ~ "Optimal",
    stringr::str_detect(x0, "mild") ~ "Mild suboptimal",
    stringr::str_detect(x0, "moderate") ~ "Moderate suboptimal",
    stringr::str_detect(x0, "severe") ~ "Severe suboptimal",
    stringr::str_detect(x0, "critical") ~ "Critical penalty",
    stringr::str_detect(x0, "governance") ~ "Governance failure",
    TRUE ~ stringr::str_to_sentence(x0)
  )
}

score_grade <- function(rcs) {
  dplyr::case_when(
    rcs >= 90 ~ "Grade A",
    rcs >= 80 ~ "Grade B",
    rcs >= 65 ~ "Grade C",
    rcs >= 50 ~ "Grade D",
    TRUE ~ "Grade E"
  )
}

profile_label <- function(x) {
  dplyr::case_when(
    x == 0 ~ "0",
    abs(x) >= 1e6 ~ paste0(format(round(x / 1e6, 1), nsmall = 1), "M"),
    TRUE ~ scales::comma(x)
  )
}

find_table_file <- function(stem, optional = FALSE) {
  pattern <- paste0("^", stem, "(\\([0-9]+\\))?\\.csv$")
  files <- list.files(table_dir, pattern = pattern, full.names = TRUE)

  if (length(files) == 0) {
    files <- list.files(
      table_dir,
      pattern = paste0(stem, ".*\\.csv$"),
      full.names = TRUE,
      ignore.case = TRUE
    )
  }

  if (length(files) == 0) {
    if (optional) return(NA_character_)
    stop("Required table not found: ", stem, ".csv in ", table_dir)
  }

  files[[1]]
}

read_table_clean <- function(stem, optional = FALSE) {
  path <- find_table_file(stem, optional = optional)

  if (is.na(path)) return(NULL)

  message("Reading table: ", basename(path))

  readr::read_csv(path, show_col_types = FALSE, progress = FALSE) |>
    clean_names()
}

read_table_raw_by_stem <- function(stem) {
  path <- find_table_file(stem, optional = TRUE)

  if (is.na(path)) return(NULL)

  readr::read_csv(path, show_col_types = FALSE, progress = FALSE)
}

save_figure <- function(plot, filename, width, height) {
  pdf_file <- file.path(figure_dir, paste0(filename, ".pdf"))
  png_file <- file.path(figure_dir, paste0(filename, ".png"))

  pdf_device <- if (capabilities("cairo")) grDevices::cairo_pdf else grDevices::pdf

  ggplot2::ggsave(
    filename = pdf_file,
    plot = plot,
    width = width,
    height = height,
    units = "in",
    device = pdf_device,
    bg = "white",
    limitsize = FALSE
  )

  ggplot2::ggsave(
    filename = png_file,
    plot = plot,
    width = width,
    height = height,
    units = "in",
    dpi = 600,
    bg = "white",
    limitsize = FALSE
  )

  message("Saved: ", pdf_file)
  message("Saved: ", png_file)
}

make_text_plot <- function(label, size = 4.2, face = "bold", hjust = 0) {
  ggplot2::ggplot() +
    ggplot2::annotate(
      "text",
      x = ifelse(hjust == 0.5, 0.5, 0),
      y = 0.5,
      label = label,
      hjust = hjust,
      vjust = 0.5,
      size = size,
      fontface = face,
      colour = "#222222",
      lineheight = 0.95
    ) +
    ggplot2::coord_cartesian(xlim = c(0, 1), ylim = c(0, 1), clip = "off") +
    ggplot2::theme_void() +
    ggplot2::theme(
      plot.margin = ggplot2::margin(t = 2, r = 6, b = 2, l = 6)
    )
}

axis_levels_for_matrix <- function(df) {
  df |>
    dplyr::distinct(axis_label, axis_order) |>
    dplyr::arrange(dplyr::desc(axis_order)) |>
    dplyr::pull(axis_label) |>
    unique()
}

