# 4. Figure 2 — Synthetic validation heatmap
# ==========================================================

make_synthetic_validation_data <- function() {
  cached_source <- file.path(
    figure_source_dir,
    "Figure_2_Source_Synthetic_Validation_Heatmap.csv"
  )

  if (file.exists(cached_source)) {
    message("Using cached Figure 2 source: ", cached_source)

    cached_df <- readr::read_csv(
      cached_source,
      show_col_types = FALSE,
      progress = FALSE
    ) |>
      clean_names()

    if (!("n" %in% names(cached_df))) {
      cached_df$n <- NA_real_
    }

    return(
      cached_df |>
        dplyr::mutate(
          matrix = factor(matrix, levels = matrix_labels),
          scenario = factor(as.character(scenario), levels = scenario_levels),
          assigned_grade = factor(as.character(assigned_grade), levels = grade_levels),
          proportion = parse_num(proportion),
          n = parse_num(n),
          label = dplyr::if_else(
            proportion >= 0.005,
            scales::percent(proportion, accuracy = 0.1),
            ""
          )
        )
    )
  }

  dist_table <- read_table_clean("Table_Synthetic_Validation_Grade_Distribution", optional = TRUE)

  if (!is.null(dist_table)) {
    df <- dist_table

    matrix_col <- find_col(
      df,
      c("matrix", "matrix_type", "biospecimen_matrix", "sample_matrix"),
      label = "matrix column"
    )

    scenario_col <- find_col(
      df,
      c(
        "scenario",
        "validation_scenario",
        "synthetic_validation_scenario",
        "expected_scenario",
        "profile_scenario"
      ),
      label = "scenario column"
    )

    grade_col <- find_col(
      df,
      c(
        "final_grade",
        "assigned_grade",
        "assigned_rcs_grade",
        "rcs_grade",
        "grade",
        "score_based_grade"
      ),
      label = "assigned grade column"
    )

    n_col <- find_col(
      df,
      c("n", "count", "profiles", "frequency", "n_profiles"),
      required = FALSE,
      label = "count column"
    )

    prop_col <- find_col(
      df,
      c("proportion", "prop", "percentage", "percent"),
      required = FALSE,
      label = "proportion column"
    )

    tmp <- df |>
      dplyr::transmute(
        matrix = normalize_matrix(.data[[matrix_col]]),
        scenario = normalize_scenario(.data[[scenario_col]]),
        assigned_grade = normalize_grade(.data[[grade_col]]),
        n = if (!is.na(n_col)) parse_num(.data[[n_col]]) else NA_real_,
        proportion_raw = if (!is.na(prop_col)) parse_num(.data[[prop_col]]) else NA_real_
      )

    if (all(is.na(tmp$n)) && any(!is.na(tmp$proportion_raw))) {
      tmp <- tmp |>
        dplyr::mutate(
          proportion = dplyr::if_else(
            proportion_raw > 1,
            proportion_raw / 100,
            proportion_raw
          ),
          n = NA_real_
        )
    } else {
      tmp <- tmp |>
        dplyr::group_by(matrix, scenario, assigned_grade) |>
        dplyr::summarise(n = sum(n, na.rm = TRUE), .groups = "drop") |>
        dplyr::group_by(matrix, scenario) |>
        dplyr::mutate(proportion = n / sum(n, na.rm = TRUE)) |>
        dplyr::ungroup()
    }

  } else {
    cohort <- read_table_clean("Synthetic_Cohort_RCS", optional = FALSE)

    matrix_col <- find_col(
      cohort,
      c("matrix", "matrix_type", "biospecimen_matrix", "sample_matrix"),
      label = "matrix column"
    )

    scenario_col <- find_col(
      cohort,
      c(
        "scenario",
        "validation_scenario",
        "synthetic_validation_scenario",
        "expected_scenario",
        "profile_scenario"
      ),
      label = "scenario column"
    )

    grade_col <- find_col(
      cohort,
      c("final_grade", "assigned_grade", "assigned_rcs_grade", "rcs_grade", "grade"),
      label = "assigned grade column"
    )

    tmp <- cohort |>
      dplyr::transmute(
        matrix = normalize_matrix(.data[[matrix_col]]),
        scenario = normalize_scenario(.data[[scenario_col]]),
        assigned_grade = normalize_grade(.data[[grade_col]])
      ) |>
      dplyr::count(matrix, scenario, assigned_grade, name = "n") |>
      dplyr::group_by(matrix, scenario) |>
      dplyr::mutate(proportion = n / sum(n)) |>
      dplyr::ungroup()
  }

  tmp |>
    dplyr::mutate(
      matrix = factor(matrix, levels = matrix_levels, labels = matrix_labels),
      scenario = factor(scenario, levels = scenario_levels),
      assigned_grade = factor(assigned_grade, levels = grade_levels)
    ) |>
    tidyr::complete(
      matrix,
      scenario,
      assigned_grade,
      fill = list(n = 0, proportion = 0)
    ) |>
    dplyr::mutate(
      label = dplyr::if_else(
        proportion >= 0.005,
        scales::percent(proportion, accuracy = 0.1),
        ""
      )
    )
}

fig2_df <- make_synthetic_validation_data()

