make_combinatorial_data <- function() {
  cached_source <- file.path(
    figure_source_dir,
    "Figure_3_Source_Combinatorial_Distribution.csv"
  )

  if (file.exists(cached_source)) {
    message("Using cached Figure 3 source: ", cached_source)

    return(
      readr::read_csv(cached_source, show_col_types = FALSE, progress = FALSE) |>
        clean_names() |>
        dplyr::mutate(
          matrix = factor(matrix, levels = matrix_labels),
          grade = factor(as.character(grade), levels = grade_levels),
          n = parse_num(n),
          proportion = parse_num(proportion),
          label = dplyr::if_else(
            is.na(label) | label == "",
            paste0(scales::percent(proportion, accuracy = 0.1), "\n", "n=", scales::comma(n)),
            as.character(label)
          )
        )
    )
  }

  df <- read_table_clean("Table_Combinatorial_Grade_Distribution", optional = FALSE)

  matrix_col <- find_col(
    df,
    c("matrix", "matrix_type", "biospecimen_matrix", "sample_matrix"),
    label = "matrix column"
  )

  grade_col <- find_col(
    df,
    c("grade", "final_grade", "score_based_grade", "assigned_grade", "rcs_grade"),
    label = "grade column"
  )

  n_col <- find_col(
    df,
    c("n", "count", "profiles", "frequency", "n_profiles"),
    label = "count column"
  )

  prop_col <- find_col(
    df,
    c("proportion", "prop", "percentage", "percent"),
    required = FALSE,
    label = "proportion column"
  )

  tmp <- df |>
    dplyr::transmute(
      matrix = normalize_matrix(.data[[matrix_col]]),
      grade = normalize_grade(.data[[grade_col]]),
      n = parse_num(.data[[n_col]]),
      proportion_raw = if (!is.na(prop_col)) parse_num(.data[[prop_col]]) else NA_real_
    )

  if (any(!is.na(tmp$proportion_raw))) {
    tmp <- tmp |>
      dplyr::mutate(
        proportion = dplyr::if_else(
          proportion_raw > 1,
          proportion_raw / 100,
          proportion_raw
        )
      )
  } else {
    tmp <- tmp |>
      dplyr::group_by(matrix) |>
      dplyr::mutate(proportion = n / sum(n, na.rm = TRUE)) |>
      dplyr::ungroup()
  }

  tmp |>
    dplyr::mutate(
      matrix = factor(matrix, levels = matrix_levels, labels = matrix_labels),
      grade = factor(grade, levels = grade_levels),
      label = paste0(
        scales::percent(proportion, accuracy = 0.1),
        "\n",
        "n=",
        scales::comma(n)
      )
    ) |>
    tidyr::complete(
      matrix,
      grade,
      fill = list(n = 0, proportion = 0, label = "")
    )
}

