# ==========================================================
# 6. Figure 4 — Threshold-transition stability summary
# ==========================================================
#
# CMPB/Elsevier rationale:
#   The previous version displayed the full perturbation-by-threshold matrix
#   inside the main figure, which made the image too dense for journal review.
#   This version generates a concise main figure showing the number of
#   perturbation scenarios, out of five, in which each isolated axis reached
#   each grade-transition threshold. The full matrix is preserved as a source
#   CSV for auditability and supplementary use.
# ==========================================================

make_figure4_data <- function() {
  summary_path <- file.path(
    figure_source_dir,
    "Figure_4_Source_Threshold_Transition_Summary.csv"
  )

  full_path <- file.path(
    figure_source_dir,
    "Figure_4_Source_Full_Threshold_Crossing_Matrix.csv"
  )

  old_detail_path <- file.path(
    figure_source_dir,
    "Figure_4_Source_Panel_A_Threshold_Crossing_Matrix.csv"
  )

  if (file.exists(summary_path)) {
    message("Using cached Figure 4 summary source: ", summary_path)

    summary_df <- readr::read_csv(
      summary_path,
      show_col_types = FALSE,
      progress = FALSE
    ) |>
      clean_names()

    if ("transition_label" %in% names(summary_df)) {
      transition_values <- as.character(summary_df$transition_label)
    } else if ("threshold_transition" %in% names(summary_df)) {
      transition_values <- as.character(summary_df$threshold_transition)
    } else {
      transition_values <- rep(NA_character_, nrow(summary_df))
    }

    if (!("total_n" %in% names(summary_df))) {
      summary_df$total_n <- 5
    }

    if (!("reached_label" %in% names(summary_df))) {
      summary_df$reached_label <- NA_character_
    }

    summary_df$transition_label <- transition_values

    # Normalize expected columns if they already exist.
    summary_df <- summary_df |>
      dplyr::mutate(
        matrix = as.character(matrix),
        matrix = dplyr::case_when(
          stringr::str_detect(tolower(matrix), "fluid") ~ "Fluid biospecimens",
          stringr::str_detect(tolower(matrix), "solid") ~ "Solid biospecimens",
          TRUE ~ matrix
        ),
        transition_label = stringr::str_replace_all(transition_label, "A to B|A--B|A-B", "A\u2192B"),
        transition_label = stringr::str_replace_all(transition_label, "B to C|B--C|B-C", "B\u2192C"),
        transition_label = stringr::str_replace_all(transition_label, "C to D|C--D|C-D", "C\u2192D"),
        transition_label = stringr::str_replace_all(transition_label, "D to E|D--E|D-E", "D\u2192E"),
        reached_n = parse_num(reached_n),
        total_n = parse_num(total_n),
        reached_label = dplyr::if_else(
          is.na(reached_label) | reached_label == "",
          paste0(reached_n, "/", total_n),
          as.character(reached_label)
        )
      )

    return(summary_df)
  }

  if (file.exists(full_path)) {
    message("Using cached Figure 4 full source: ", full_path)

    full_df <- readr::read_csv(
      full_path,
      show_col_types = FALSE,
      progress = FALSE
    ) |>
      clean_names()
  } else if (file.exists(old_detail_path)) {
    message("Using legacy Figure 4 source: ", old_detail_path)

    full_df <- readr::read_csv(
      old_detail_path,
      show_col_types = FALSE,
      progress = FALSE
    ) |>
      clean_names()
  } else {
    stop(
      "No Figure 4 source table found. Expected one of: ",
      summary_path, " ; ", full_path, " ; ", old_detail_path
    )
  }

  # Normalize detailed source columns.
  matrix_col <- find_col(full_df, c("matrix"), label = "Figure 4 matrix column")
  axis_col <- find_col(full_df, c("axis"), required = FALSE, label = "Figure 4 axis column")
  axis_label_col <- find_col(full_df, c("axis_label"), label = "Figure 4 axis label column")
  axis_order_col <- find_col(full_df, c("axis_order"), label = "Figure 4 axis order column")
  transition_col <- find_col(
    full_df,
    c("threshold_transition", "transition", "grade_transition"),
    label = "Figure 4 transition column"
  )
  transition_label_col <- find_col(
    full_df,
    c("transition_label"),
    required = FALSE,
    label = "Figure 4 transition label column"
  )
  reached_col <- find_col(full_df, c("reached"), label = "Figure 4 reached column")
  severity_col <- find_col(
    full_df,
    c("severity_required", "severity_plot"),
    required = FALSE,
    label = "Figure 4 severity column"
  )

  summary_df <- full_df |>
    dplyr::transmute(
      matrix = .data[[matrix_col]],
      axis = if (!is.na(axis_col)) as.character(.data[[axis_col]]) else as.character(.data[[axis_label_col]]),
      axis_label = as.character(.data[[axis_label_col]]),
      axis_order = parse_num(.data[[axis_order_col]]),
      threshold_transition = as.character(.data[[transition_col]]),
      transition_label = if (!is.na(transition_label_col)) {
        as.character(.data[[transition_label_col]])
      } else {
        as.character(.data[[transition_col]])
      },
      reached = as.logical(.data[[reached_col]]),
      severity_required = if (!is.na(severity_col)) parse_num(.data[[severity_col]]) else NA_real_
    ) |>
    dplyr::mutate(
      matrix = dplyr::case_when(
        stringr::str_detect(tolower(as.character(matrix)), "fluid") ~ "Fluid biospecimens",
        stringr::str_detect(tolower(as.character(matrix)), "solid") ~ "Solid biospecimens",
        TRUE ~ as.character(matrix)
      ),
      transition_label = stringr::str_replace_all(transition_label, "A to B|A--B|A-B", "A\u2192B"),
      transition_label = stringr::str_replace_all(transition_label, "B to C|B--C|B-C", "B\u2192C"),
      transition_label = stringr::str_replace_all(transition_label, "C to D|C--D|C-D", "C\u2192D"),
      transition_label = stringr::str_replace_all(transition_label, "D to E|D--E|D-E", "D\u2192E")
    ) |>
    dplyr::group_by(
      matrix,
      axis,
      axis_label,
      axis_order,
      threshold_transition,
      transition_label
    ) |>
    dplyr::summarise(
      reached_n = sum(reached, na.rm = TRUE),
      total_n = dplyr::n(),
      min_severity_reached = ifelse(
        any(reached),
        min(severity_required[reached], na.rm = TRUE),
        NA_real_
      ),
      .groups = "drop"
    ) |>
    dplyr::mutate(
      reached_label = paste0(reached_n, "/", total_n)
    )

  readr::write_csv(
    summary_df,
    summary_path
  )

  summary_df
}

fig4_summary <- make_figure4_data()

