# ==========================================================
# 7. Figure 5 — Runtime scalability
# ==========================================================

make_runtime_data <- function() {
  cached_raw <- file.path(
    figure_source_dir,
    "Figure_5_Source_Runtime_Raw.csv"
  )

  cached_summary <- file.path(
    figure_source_dir,
    "Figure_5_Source_Runtime_Summary.csv"
  )

  if (file.exists(cached_raw) && file.exists(cached_summary)) {
    message("Using cached Figure 5 source tables.")

    raw_plot <- readr::read_csv(cached_raw, show_col_types = FALSE, progress = FALSE) |>
      clean_names()

    summary_plot <- readr::read_csv(cached_summary, show_col_types = FALSE, progress = FALSE) |>
      clean_names()

    raw_plot <- raw_plot |>
      dplyr::mutate(
        n_profiles = parse_num(n_profiles),
        elapsed_seconds = parse_num(elapsed_seconds)
      )

    summary_plot <- summary_plot |>
      dplyr::mutate(
        n_profiles = parse_num(n_profiles),
        mean_elapsed_seconds = if ("mean_elapsed_seconds" %in% names(summary_plot)) {
          parse_num(mean_elapsed_seconds)
        } else {
          NA_real_
        },
        mean_cost_us = parse_num(mean_cost_us)
      )

    lm_fit <- stats::lm(elapsed_seconds ~ n_profiles, data = raw_plot)
    r2 <- summary(lm_fit)$r.squared
    slope <- unname(stats::coef(lm_fit)[["n_profiles"]])

    return(
      list(
        raw = raw_plot,
        summary = summary_plot,
        r2 = r2,
        slope = slope
      )
    )
  }

  summary_df <- read_table_clean("Table_Runtime_Benchmark_Summary", optional = TRUE)
  raw_df <- read_table_clean("Table_Runtime_Benchmark_Raw", optional = TRUE)

  if (!is.null(raw_df)) {
    n_col <- find_col(
      raw_df,
      c("n_profiles", "profiles", "n_records", "records", "n", "cohort_size", "sample_size"),
      label = "runtime profile-count column"
    )

    elapsed_col <- find_col(
      raw_df,
      c(
        "elapsed_seconds",
        "elapsed_sec",
        "elapsed_time",
        "time_seconds",
        "time_sec",
        "runtime_seconds",
        "seconds"
      ),
      label = "runtime elapsed-time column"
    )

    raw_plot <- raw_df |>
      dplyr::transmute(
        n_profiles = parse_num(.data[[n_col]]),
        elapsed_seconds = parse_num(.data[[elapsed_col]])
      ) |>
      dplyr::filter(is.finite(n_profiles), is.finite(elapsed_seconds))

  } else if (!is.null(summary_df)) {
    n_col <- find_col(
      summary_df,
      c("n_profiles", "profiles", "n_records", "records", "n", "cohort_size", "sample_size"),
      label = "runtime profile-count column"
    )

    elapsed_col <- find_col(
      summary_df,
      c(
        "mean_elapsed_seconds",
        "mean_elapsed_sec",
        "elapsed_seconds",
        "elapsed_sec",
        "mean_seconds",
        "runtime_seconds",
        "seconds"
      ),
      label = "runtime elapsed-time column"
    )

    raw_plot <- summary_df |>
      dplyr::transmute(
        n_profiles = parse_num(.data[[n_col]]),
        elapsed_seconds = parse_num(.data[[elapsed_col]])
      ) |>
      dplyr::filter(is.finite(n_profiles), is.finite(elapsed_seconds))

  } else {
    stop("Runtime benchmark tables were not found.")
  }

  summary_plot <- raw_plot |>
    dplyr::group_by(n_profiles) |>
    dplyr::summarise(
      mean_elapsed_seconds = mean(elapsed_seconds, na.rm = TRUE),
      .groups = "drop"
    ) |>
    dplyr::mutate(
      mean_cost_us = mean_elapsed_seconds / n_profiles * 1e6
    )

  if (!is.null(summary_df)) {
    n_col_sum <- find_col(
      summary_df,
      c("n_profiles", "profiles", "n_records", "records", "n", "cohort_size", "sample_size"),
      required = FALSE,
      label = "summary profile-count column"
    )

    cost_col_sum <- find_col(
      summary_df,
      c(
        "mean_per_sample_microsec",
        "mean_per_profile_microsec",
        "mean_cost_us",
        "mean_cost_microsec",
        "per_sample_microsec",
        "per_profile_microsec",
        "microseconds_per_sample",
        "microseconds_per_profile"
      ),
      required = FALSE,
      label = "summary per-profile cost column"
    )

    if (!is.na(n_col_sum) && !is.na(cost_col_sum)) {
      cost_from_summary <- summary_df |>
        dplyr::transmute(
          n_profiles = parse_num(.data[[n_col_sum]]),
          mean_cost_us_summary = parse_num(.data[[cost_col_sum]])
        ) |>
        dplyr::filter(is.finite(n_profiles), is.finite(mean_cost_us_summary)) |>
        dplyr::group_by(n_profiles) |>
        dplyr::summarise(
          mean_cost_us_summary = mean(mean_cost_us_summary, na.rm = TRUE),
          .groups = "drop"
        )

      if (nrow(cost_from_summary) > 0) {
        summary_plot <- summary_plot |>
          dplyr::left_join(cost_from_summary, by = "n_profiles") |>
          dplyr::mutate(
            mean_cost_us = dplyr::coalesce(mean_cost_us_summary, mean_cost_us)
          ) |>
          dplyr::select(-mean_cost_us_summary)
      }
    }
  }

  lm_fit <- stats::lm(elapsed_seconds ~ n_profiles, data = raw_plot)
  r2 <- summary(lm_fit)$r.squared
  slope <- unname(stats::coef(lm_fit)[["n_profiles"]])

  list(
    raw = raw_plot,
    summary = summary_plot,
    r2 = r2,
    slope = slope
  )
}

