# ==========================================================
# 8. Supplementary audit tables
# ==========================================================

supplementary_index <- tibble::tibble(
  file_name = character(),
  source_tables = character(),
  description = character(),
  status = character()
)

add_supplementary_index <- function(file_name, source_tables, description, status) {
  supplementary_index <<- dplyr::bind_rows(
    supplementary_index,
    tibble::tibble(
      file_name = file_name,
      source_tables = source_tables,
      description = description,
      status = status
    )
  )
}

write_combined_supplementary_table <- function(stems, out_file, description) {
  dfs <- list()
  found <- character()

  for (stem in stems) {
    raw_df <- read_table_raw_by_stem(stem)

    if (!is.null(raw_df)) {
      found <- c(found, stem)

      raw_df <- raw_df |>
        dplyr::mutate(
          source_table = stem,
          .before = 1
        ) |>
        dplyr::mutate(
          dplyr::across(dplyr::everything(), as.character)
        )

      dfs[[stem]] <- raw_df
    }
  }

  if (length(dfs) == 0) {
    add_supplementary_index(
      file_name = out_file,
      source_tables = paste(stems, collapse = "; "),
      description = description,
      status = "not generated; source table not found"
    )
    message("Skipped supplementary table because source table was not found: ", out_file)
    return(invisible(NULL))
  }

  combined <- dplyr::bind_rows(dfs)

  readr::write_csv(
    combined,
    file.path(supplementary_dir, out_file)
  )

  add_supplementary_index(
    file_name = out_file,
    source_tables = paste(found, collapse = "; "),
    description = description,
    status = "generated"
  )

  message("Generated supplementary table: ", out_file)
}

