  stems = c("Table_Property_Based_Checks"),
  out_file = "Additional_File_S4_Property_Based_Logical_Checks.csv",
  description = "Property-based logical checks validating deterministic behaviour, bounded penalties, monotonicity, matrix-specific axes, and governance override."
)

